INSERT INTO questions (test_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, category, difficulty)
VALUES
-- Светофоры (Traffic Lights) - 10 вопросов
(1, 'Что обозначает красный сигнал светофора?', 'Разрешение на движение', 'Необходимо остановиться', 'Подготовка к движению', 'Внимание', 'B', 'Красный сигнал светофора означает, что водитель должен остановиться перед стоп-линией и не может ехать дальше.', 'lights', 'easy'),
(1, 'Что обозначает желтый сигнал светофора?', 'Разрешение на движение', 'Подготовиться к смене сигнала', 'Обязательная остановка', 'Немедленно выключить машину', 'B', 'Желтый сигнал означает, что сигнал вот-вот изменится на красный или зеленый. Это предупреждение для водителя.', 'lights', 'easy'),
(1, 'Что обозначает зеленый сигнал светофора?', 'Остановка требуется', 'Разрешение на движение', 'Снизить скорость', 'Припарковаться перед стоп-линией', 'B', 'Зеленый сигнал разрешает водителю двигаться вперед в направлении движения.', 'lights', 'easy'),
(1, 'Как проехать на мигающий желтый сигнал?', 'Проезд полностью запрещен', 'Можно проехать если позволяет машинопоток', 'Можно проехать с проверкой безопасности', 'Во всех случаях требуется остановиться', 'C', 'Мигающий желтый сигнал разрешает проезд после проверки безопасности перекрестка.', 'lights', 'normal'),
(1, 'Как следует действовать на мигающий зеленый сигнал?', 'Можно проехать без опасений', 'Обязательно ехать быстрее', 'Проехать, проверив безопасность', 'Никогда не проезжать', 'C', 'Мигающий зеленый сигнал означает, что скоро загорится красный - нужна осторожность.', 'lights', 'normal'),
(1, 'Может ли водитель повернуть налево на красный сигнал?', 'Да', 'Нет', 'Только если разрешено', 'Зависит от типа машины', 'B', 'На красный сигнал все движения и повороты полностью запрещены правилами.', 'lights', 'normal'),
(1, 'Что делать, если светофор не работает (потушен)?', 'Можно проехать свободно', 'Ехать осторожно, включить аварийный сигнал', 'Ехать с высокой скоростью', 'Игнорировать все сигналы', 'B', 'При неисправном светофоре необходимо ехать осторожно и включить аварийные огни.', 'lights', 'normal'),
(1, 'Что означает мигающий красный сигнал светофора?', 'Необходимо срочно проехать', 'Требуется остановка на перекрестке', 'Нужно пропустить встречный транспорт', 'Все машины должны остановиться', 'C', 'Мигающий красный означает требуется остановка как на стоп-линии у перекрестка.', 'lights', 'hard'),
(1, 'Какую роль выполняет непрерывно горящий желтый сигнал?', 'Разрешает проезд', 'Требует остановку', 'Предупреждает об изменении сигнала', 'Требует выключить машину', 'C', 'Желтый сигнал предупреждает об изменении сигнала светофора.', 'lights', 'normal'),
(1, 'На какие стороны разрешен проезд на зеленый сигнал?', 'Только прямо', 'Прямо и налево', 'Прямо и направо', 'Во все стороны и повороты', 'D', 'На зеленый сигнал разрешено движение во всех направлениях.', 'lights', 'easy'),

-- Дорожные знаки (Road Signs) - 10 вопросов
(1, 'На сколько основных групп разделены дорожные знаки в России?', '5 групп', '6 групп', '8 групп', '10 групп', 'C', 'Дорожные знаки разделены на 8 основных категорий: запретительные, предписывающие, предупреждающие, информационные и другие.', 'signs', 'normal'),
(1, 'Какие цвета используются в запретительных знаках?', 'Красный круг с белой линией', 'Синий квадрат', 'Зеленый квадрат', 'Желтый ромб', 'A', 'Запретительные знаки имеют красный круг с белой окантовкой.', 'signs', 'normal'),
(1, 'Как выглядит знак «Въезд запрещен»?', 'Белый X на черном диске', 'Красный круг с белой линией', 'Зеленый квадрат', 'Желтый ромб', 'A', 'Знак «Въезд запрещен» выглядит как белый X на черном диске. Въезд запрещен.', 'signs', 'easy'),
(1, 'Как выглядит знак «Стоянка запрещена»?', 'Красный круг с буквой X', 'Желтый ромб', 'Синий квадрат', 'Черный диск', 'A', 'Знак «Стоянка запрещена» выглядит как красный круг с одной линией.', 'signs', 'normal'),
(1, 'Как выглядит знак парковки?', 'Красный X', 'Синий квадрат с буквой P', 'Зеленая букв P', 'Белый квадрат', 'A', 'Знак парковки имеет синий фон с буквой P. Запрет парковки - красный X.', 'signs', 'normal'),
(1, 'Какую форму имеют предупреждающие знаки?', 'Черный квадрат', 'Белый треугольник с красной окантовкой', 'Красный круг', 'Зеленый квадрат', 'B', 'Предупреждающие знаки имеют форму белого треугольника с красной каймой.', 'signs', 'easy'),
(1, 'Какой цвет используется для информационных знаков?', 'Красный диск', 'Синий квадрат', 'Желтый ромб', 'Белый квадрат', 'B', 'Информационные знаки выполнены в синем квадрате. Указывают парковки, АЗС и другое.', 'signs', 'hard'),
(1, 'Как обозначается главная дорога?', 'Белый треугольник', 'Желтый ромб', 'Красный круг', 'Зеленый квадрат', 'B', 'Главная дорога обозначена желтым ромбом. На такой дороге водитель имеет преимущество.', 'signs', 'normal'),
(1, 'Какой цвет используется для предписывающих знаков?', 'Черный квадрат', 'Синий квадрат с белым символом', 'Желтый ромб', 'Белый круг', 'B', 'Предписывающие знаки - синий квадрат с белым символом. Водитель обязан выполнить требование.', 'signs', 'normal'),
(1, 'Как выглядит знак обязательного направления?', 'Синий квадрат с стрелкой', 'Красный круг с линией', 'Желтый ромб', 'Черный диск', 'A', 'Знак направления движения - синий квадрат со стрелкой. Водитель должен ехать в этом направлении.', 'signs', 'normal'),

-- Правила дорожного движения (Road Rules) - 10 вопросов
(1, 'Как должен двигаться пешеход при переходе дороги?', 'В направлении транспорта', 'Навстречу транспорту', 'В любом направлении', 'Очень быстро', 'B', 'Пешеход должен двигаться навстречу транспорту чтобы видеть приближающиеся машины.', 'rules', 'easy'),
(1, 'Обязательно ли пристегиваться ремнем безопасности?', 'Нет такого правила', 'Да, это обязательно', 'Только для детей', 'Только для боковых мест', 'B', 'На всех местах в машине обязательно пристегиваться ремнем безопасности.', 'rules', 'easy'),
(1, 'Какое максимальное ограничение скорости в городе?', '40 км/ч', '50 км/ч', '60 км/ч', '80 км/ч', 'C', 'Максимальная скорость в городе - 60 км/ч. В жилых районах - 20 км/ч.', 'rules', 'easy'),
(1, 'Какова максимальная скорость на магистрали?', '60 км/ч', '80 км/ч', '90 км/ч', '110 км/ч', 'D', 'На магистралях максимальная скорость - 110 км/ч. Знаки могут изменять это значение.', 'rules', 'normal'),
(1, 'Обязательно ли мотоциклист не должен носить шлем?', 'Нет такого закона', 'Да, это обязательно', 'Только ночью', 'В зависимости от погоды', 'B', 'Мотоциклист обязан носить защитный шлем при езде.', 'rules', 'normal'),
(1, 'Как проехать припаркованную машину?', 'Никогда нельзя проезжать', 'Можно отвести машину в сторону', 'Нужно проезжать с проверкой безопасности', 'Можно ехать с высокой скоростью', 'C', 'Припаркованную машину можно проезжать проверив безопасность маневра.', 'rules', 'normal'),
(1, 'Кому имеет право машина на круговом перекрестке?', 'Машинам выезжающим с круга', 'Машинам находящимся на кругу', 'Всем машинам одинаково', 'Машинам снаружи круга', 'B', 'На круговом перекрестке имеют преимущество машины находящиеся на кругу.', 'rules', 'normal'),
(1, 'Какое преимущество имеет трамвай?', 'Одинаковое преимущество', 'Трамвай имеет преимущество', 'Легковая машина имеет преимущество', 'Преимущество трамвая в конце маршрута', 'B', 'Трамвай имеет преимущество перед машинами. Водитель обязан пропустить трамвай.', 'rules', 'hard'),
(1, 'Что обязательно включить при повороте?', 'Регулировку скорости', 'Включить фары', 'Поворотник (сигнал поворота)', 'Ничего не требуется', 'C', 'При повороте обязательно включить поворотник. Это предупреждает других водителей.', 'rules', 'easy'),
(1, 'Можно ли ехать на пешеходный переход?', 'Да если машина проезжает быстро', 'Нет это запрещено', 'Только если нет пешеходов', 'Только ночью', 'B', 'Машина не может ехать по пешеходному переходу. Водитель должен пропустить пешеходов.', 'rules', 'easy'),

-- Безопасность (Safety) - 10 вопросов
(1, 'Как часто требуется техническое обслуживание машины?', 'Один раз в год', 'Два раза в год', 'Четыре раза в год', 'Техническое обслуживание не требуется', 'A', 'Техническое обслуживание машины обязательно один раз в год.', 'safety', 'normal'),
(1, 'Обязательны ли детские автокресла?', 'Необязательно', 'Обязательно для всех детей', 'Только для детей до 5 лет', 'Можно сидеть на обычном сиденье', 'B', 'Все дети обязаны сидеть в специальных автокреслах. Это требование безопасности для детей до 12 лет.', 'safety', 'easy'),
